#!/bin/sh
# SPDX-License-Identifier: GPL-3.0-or-later
# Device list of docs/USERGUIDE.txt, generated from devices/*.dev.
#
# usage: tools/mkdevlist.sh            print the list
#        tools/mkdevlist.sh GUIDE.txt  replace the lines between the
#                                      markers "(device list generated by
#                                      tools/mkdevlist.sh)" and "(end of
#                                      device list)"
# Every mnemonic needs a partname line.  When freecupl is built (or
# $FREECUPL is set) the mnemonics must match freecupl -devices.
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
TMP="${TMPDIR:-/tmp}/mkdevlist.$$"
mkdir "$TMP" || exit 2
trap 'rm -rf "$TMP"' EXIT INT TERM

# family titles, in the order of the list
FILES="v10 gal8 gal_vp8 gal_z8 gal16h m16v8 gal24 gal_xv10 peel18 atv750 atv2500 atv5000
pal20_small pal64 pal_steer pal_xrp pal_mega m3_gal m3_pal_fixed m3_pal_p
m3_pal_rp m3_pal_olmc m3_pal_10k m3_pal_inreg m3_pal_latch m3_pal_x m3_ra
m3_misc lcc m3_lcc"
title() {
    case "$1" in
    v10)          echo "22V10 (PAL22V10, GAL22V10, ATF22V10B/C)" ;;
    gal8)         echo "GAL16V8 / GAL20V8 and equivalents" ;;
    gal_vp8)      echo "GAL16VP8 / GAL20VP8" ;;
    gal_z8)       echo "GAL16Z8 / GAL20Z8 (zero-power)" ;;
    gal16h)       echo "GAL16V8 variants with input latches (24 pins)" ;;
    m16v8)        echo "MMI-type 16V8" ;;
    gal24)        echo "GAL24V10-type" ;;
    gal_xv10)     echo "GAL20XV10" ;;
    peel18)       echo "PEEL18CV8-type" ;;
    atv750)       echo "ATV750 / ATF750C family" ;;
    atv2500)      echo "ATV2500 / ATF2500C family" ;;
    atv5000)      echo "ATV5000" ;;
    pal20_small)  echo "Small 20-pin combinational PALs" ;;
    pal64)        echo "20- and 24-pin PALs with 64 product terms" ;;
    pal_steer)    echo "Product-term steering PALs" ;;
    pal_xrp)      echo "PAL20XRP registered XOR PALs with programmable polarity" ;;
    pal_mega)     echo "MegaPAL (PAL32R16 / PAL64R32)" ;;
    m3_gal)       echo "Other GAL and GAL-like parts" ;;
    m3_pal_fixed) echo "Fixed-polarity combinational PALs" ;;
    m3_pal_p)     echo "Programmable-polarity combinational PALs" ;;
    m3_pal_rp)    echo "Registered PALs with programmable polarity" ;;
    m3_pal_olmc)  echo "PALs with configurable output macrocells" ;;
    m3_pal_10k)   echo "24-pin PALs with the 10H/10K-style pinout" ;;
    m3_pal_inreg) echo "PALs with registered or latched inputs" ;;
    m3_pal_latch) echo "PALs with latched outputs" ;;
    m3_pal_x)     echo "Registered XOR PALs" ;;
    m3_ra)        echo "Asynchronous registered PALs" ;;
    m3_misc)      echo "Other directly compiled parts" ;;
    lcc)          echo "LCC/PLCC package variants (22V10, GAL16V8/20V8, PAL16/20 series)" ;;
    m3_lcc)       echo "LCC/PLCC package variants of the other families" ;;
    *)            echo "$1" ;;
    esac
}

# every description file needs a title
for f in "$ROOT"/devices/*.dev; do
    b=$(basename "$f" .dev)
    case " $(echo $FILES) " in *" $b "*) ;; *) echo "mkdevlist: $b.dev has no family title" >&2; exit 1 ;; esac
done

for b in $FILES; do echo "$ROOT/devices/$b.dev"; done | xargs awk '
# first collect every description, then resolve inherit (the parent may be
# in a later file) and print in file order
function val(d, k,   v) {
    v = (k == "p") ? P[d] : F[d]
    if (v == "" && PAR[d] != "" && PAR[d] != d) return val(PAR[d], k)
    return v == "" ? "?" : v
}
FNR == 1 { file = FILENAME; sub(/.*\//, "", file); sub(/\.dev$/, "", file) }
{ sub(/#.*/, ""); sub(/\r$/, "") }
$1 == "device"  { dev = $2; nd++; ORD[nd] = dev; FI[dev] = file; NA[dev] = 0; next }
$1 == "inherit" { PAR[dev] = $2; next }
$1 == "pins"    { P[dev] = $2; next }
$1 == "fuses"   { F[dev] = $2; next }
$1 == "descr"   {
    # free text; drop build notes (tool paths) and internal family tags
    $1 = ""; sub(/^ +/, ""); gsub(/\|/, "/"); gsub(/;? *tools\/[^ ;)]*/, "")
    sub(/ *\([a-z][a-z0-9_]*\)$/, ""); sub(/ *\( *\)$/, ""); DE[dev] = $0; next
}
$1 == "alias"   {
    k = ++NA[dev]; AN[dev, k] = $2; m = "-"
    if ($3 == "simple" || $3 == "complex" || $3 == "registered" || $3 == "auto") m = $3
    AM[dev, k] = m; next
}
$1 == "partname" {
    # part name of one mnemonic (an alias, or the description itself)
    mn = $2; $1 = ""; $2 = ""; sub(/^ +/, ""); gsub(/\|/, "/"); PN[dev, mn] = $0; next
}
END {
    for (j = 1; j <= nd; j++) {
        d = ORD[j]; ds = DE[d] != "" ? DE[d] : toupper(d)
        if (NA[d] == 0) { NA[d] = 1; AN[d, 1] = d; AM[d, 1] = "-" }
        for (i = 1; i <= NA[d]; i++) {
            if ((d SUBSEP AN[d, i]) in PN) pn = PN[d, AN[d, i]]
            else { pn = ds; printf "mkdevlist: no partname for %s\n", AN[d, i] > "/dev/stderr"; bad = 1 }
            printf "%s\t%s\t%s\t%s\t%s\t%s\n", FI[d], AN[d, i], val(d, "p"), val(d, "f"), AM[d, i], pn
        }
    }
    exit bad
}' > "$TMP/list" || exit 1

# compare with the compiler
FC="${FREECUPL:-}"
if [ -z "$FC" ]; then
    for c in "$ROOT"/build/linux/freecupl "$ROOT"/build/macos/freecupl; do
        [ -x "$c" ] && { FC="$c"; break; }
    done
fi
if [ -n "$FC" ]; then
    cut -f2 "$TMP/list" | sort > "$TMP/a"
    "$FC" -devices | tr -d '\r' | sort > "$TMP/b"
    if ! cmp -s "$TMP/a" "$TMP/b"; then
        echo "mkdevlist: the mnemonics of devices/*.dev differ from freecupl -devices:" >&2
        diff "$TMP/a" "$TMP/b" >&2
        exit 1
    fi
fi

n=$(wc -l < "$TMP/list" | tr -d ' ')
{
    for b in $FILES; do
        awk -F '\t' -v f="$b" -v t="$(title "$b")" '
            # part name wrapped at 76 columns, continuation under the
            # part column
            function out(mn, p, fz, md, pn,   w, l, i, k, ind) {
                l = sprintf("  %-15s%4s %6s  %-11s", mn, p, fz, md)
                ind = sprintf("%" length(l) "s", "")
                k = split(pn, w, " ")
                for (i = 1; i <= k; i++) {
                    if (length(l) + 1 + length(w[i]) > 76 && l != ind) { print l; l = ind }
                    l = l (l == ind || substr(l, length(l)) == " " ? "" : " ") w[i]
                }
                print l
            }
            $1 == f {
                if (!h) {
                    printf "\n%s\n\n", t
                    printf "  %-15s%4s %6s  %-11s%s\n", "mnemonic", "pins", "fuses", "mode", "part"
                    h = 1
                }
                out($2, $3, $4, $5, $6)
            }' "$TMP/list"
    done
    echo
    echo "$n mnemonics."
} > "$TMP/txt"

if [ $# -eq 0 ]; then
    cat "$TMP/txt"
    exit 0
fi
G="$1"
BEGIN_L='(device list generated by tools/mkdevlist.sh)'
END_L='(end of device list)'
grep -qxF "$BEGIN_L" "$G" && grep -qxF "$END_L" "$G" || {
    echo "mkdevlist: $G has no marker lines \"$BEGIN_L\" and \"$END_L\"" >&2; exit 1; }
awk -v txt="$TMP/txt" -v b="$BEGIN_L" -v e="$END_L" '
    $0 == b { print; while ((getline l < txt) > 0) print l; print ""; skip = 1; next }
    $0 == e { skip = 0 }
    !skip' "$G" > "$TMP/g" || exit 1
if cmp -s "$TMP/g" "$G"; then exit 0; fi
cat "$TMP/g" > "$G"
echo "mkdevlist: $G updated ($n mnemonics)"
